package com.sonopulse.echoguide

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * Licence status of a bundled media file (assets/media/media_registry.json,
 * generated by scripts/build_media_registry.py; see ASSET_LICENSES.md).
 */
enum class CommercialUse { COMMERCIAL_ALLOWED, NON_COMMERCIAL_ONLY, PERMISSION_REQUIRED, LICENSE_UNVERIFIED }

/** One registry entry: where a video / image lives, its source and licence, and an optional replacement. */
@Serializable
data class MediaEntry(
    val id: String,
    val path: String,
    val originalFilename: String? = null,
    val type: String,
    val source: String? = null,
    val sourceUrl: String? = null,
    val author: String? = null,
    val license: String? = null,
    val commercialUse: CommercialUse,
    val attributionRequired: Boolean = true,
    val shareAlike: Boolean = false,
    val replacementStatus: String? = null,
    /** Asset path that is shown instead of [path] (e.g. a commercially licensed substitute); null = [path]. */
    val replacement: String? = null
)

@Serializable
data class MediaRegistryFile(val schemaVersion: Int, val assets: List<MediaEntry>)

/**
 * Central media mapping: every video and image is loaded through [resolve], so a restricted file can
 * be replaced by setting `replacement` in the registry – no UI or playback code changes.
 * Without a registry, or without replacements, [resolve] returns the path unchanged (the app behaves
 * exactly as before). Installed together with the protocol in [EchoRepository.load].
 */
object MediaRegistry {
    const val REGISTRY_ASSET = "media/media_registry.json"

    private val json = Json { ignoreUnknownKeys = true }

    @Volatile
    private var entries: Map<String, MediaEntry> = emptyMap()

    @Volatile
    private var replacements: Map<String, String> = emptyMap()

    fun parse(text: String): MediaRegistryFile = json.decodeFromString(MediaRegistryFile.serializer(), text)

    fun install(file: MediaRegistryFile) {
        entries = file.assets.associateBy { it.path }
        replacements = file.assets.mapNotNull { e -> e.replacement?.takeIf { it.isNotBlank() }?.let { e.path to it } }.toMap()
    }

    /** Reads the bundled registry once; a missing or unreadable registry leaves the identity mapping. */
    fun load(context: Context) {
        if (entries.isNotEmpty()) return
        runCatching {
            context.applicationContext.assets.open(REGISTRY_ASSET).bufferedReader(Charsets.UTF_8).use { install(parse(it.readText())) }
        }
    }

    /** Asset path to load for [path] (relative to assets/): its registered replacement, else [path] itself. */
    fun resolve(path: String): String = replacements[path] ?: path

    /** Coil / file URI of [path] after [resolve]. */
    fun assetUri(path: String): String = "file:///android_asset/${resolve(path)}"

    fun entry(path: String): MediaEntry? = entries[path]
}
